
.grid.slots {
  padding: 0 20px 10px;
  display: grid;
  grid-auto-rows: 100px;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  .game-slot {
    position: relative;
    // border-radius: 10px;
    overflow: hidden;
    -webkit-animation: scale 1s;
    animation: scale 1s;
    -webkit-transform: scale(0, 0);
    transform: scale(0, 0);
    -webkit-animation-fill-mode: forwards;
    animation-fill-mode: forwards;
    
    @-webkit-keyframes scale {
      100% {
        -webkit-transform: scale(1, 1);
      }
    }

    @keyframes scale {
      100% {
        transform: scale(1, 1);
      }
    }
    .slot-name {
      background: linear-gradient(0deg, #1f2035cf 20%, transparent);
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 10px;
      text-align: center;
    }
  }
}
.slots-container {
  background: linear-gradient(to bottom, #23263c, #190f25);
  .banner-container {
    @keyframes fadein {
      100% {
        opacity: 1;
      }
    }
    .promo-bg {
      background-size: cover;
      background-repeat: no-repeat;
      background-position: center center;
      overflow: hidden;
      height: 180px;
      margin: 10px;
      border-radius: 10px;

      img {
        width: 100%;
      }
    }
  }
}
.bookmarks {
  cursor: pointer;
  display: flex;
  grid-gap: 20px;
  max-width: 1400px;
  width: 100%;
  margin: 10px auto 0;
  overflow: auto;
  padding: 10px 20px 20px;
  justify-content: flex-start;
  flex-wrap: wrap;
  .plat-item {
    display: flex;
    justify-content: center;
    align-items: center;
    background: #212534;
    img {
      max-height: 15px;
      filter: grayscale(1);
    }
    span {
      color: rgba(200, 200, 200, 0.5);
      font-size: 20px;
      font-weight: bold;
    }
    &.active,
    &:hover {
      background: #2b2b4b;
      box-shadow: inset 0 0 5px #ffffff;
      img {
        filter: grayscale(0);
      }
      span {
        color: #ffffff;
      }
    }
  }
  div {
    padding: 10px;
    text-align: center;
    background: #2b2b4b;
    border-radius: 10px;
    box-shadow: rgb(0 0 0 / 24%) 0px 6px 12px 0px;
    &:hover {
      transform: scale(1.01274) translate(0px, -4px);
    }
  }
}

@media (max-width: 768px) {
  .slots-container {
    margin: 0 auto;
    .banner-container {
      .promo-bg {
        &.isDesktop {
          display: none;
        }
        &.isMobile {
          display: block;
        }
      }
    }

