@import '~src/css/quasar.variables.scss', 'quasar/src/css/variables.sass';

$group-color: #76c034;
$node-color: #dd4645;
.title {
  color: $group-color;
  margin: 10px auto;
  position: relative;
  margin-left: 18px;
  margin-bottom: 10px;
}
.title::before,
.title::after {
  content: "";
  position: absolute;
  top: 8px;
  width: 6px;
  height: 6px;
  background-image: linear-gradient(0deg, #04a509 0%, $group-color 100%),
    linear-gradient(#ffffff, #ffffff);
}
.title::before {
  top: 8px;
  left: -16px;
}
.title::after {
  top: 15px;
  left: -10px;
}
.payment-method-wrapper {
  // display: grid;
  // grid-template-columns: repeat(auto-fill, 200px);
  // grid-gap: 20px;
  // margin-top: 10px;
  display: flex;
  grid-gap: 20px;
  margin-top: 20px;
  flex-wrap: wrap;
  padding-bottom: 20px;

  .payment-method-item {
    text-align: center;
    border-radius: 6px;
    border: solid 1px #484460;
    color: #ffffff;
    cursor: pointer;
    padding: 20px 35px;
    &:hover {
      // border-bottom: 3px solid rgba(255, 255, 255, .4);
    }
    &.active {
      // background: rgba(255,255,255, .2);
      border-color: $node-color;
    }

    // &.node-group {
    //   color: $group-color;
    //   &.active{
    //     border-color: $group-color;
    //   }
    // }

    img {
      max-width: 50px;
      margin-bottom: 10px;
    }
  }
}
.container {
  margin: -20px;
}
.container > .node:first-of-type {
  margin-top: 0;
}
.container > .node:first-of-type {
  padding: 500px;
}
.node:not(.node) {
  border-bottom: 1px solid #484460;
